CREATE TABLE "Accounts" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "Email" character varying(256) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" integer NOT NULL,
    "IsLocked" boolean DEFAULT FALSE,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "RefreshToken" text,
    "RefreshTokenExpiry" timestamp with time zone,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__Accounts__3214EC0786267B8F" PRIMARY KEY ("Id")
);


CREATE TABLE "MonthlyProjectCosts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CostMonth" date NOT NULL,
    "Name" character varying(200) NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_MonthlyProjectCosts" PRIMARY KEY ("Id")
);


CREATE TABLE "SystemSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "SettingKey" character varying(100) NOT NULL,
    "SettingValue" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SystemSettings" PRIMARY KEY ("Id")
);


CREATE TABLE "WebsiteTraffic" (
    "TrafficDate" date NOT NULL,
    "Path" character varying(500) NOT NULL,
    "VisitCount" bigint NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_WebsiteTraffic" PRIMARY KEY ("TrafficDate", "Path")
);


CREATE TABLE "Admins" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "AccountId" uuid NOT NULL,
    "FullName" character varying(256) NOT NULL,
    "SuperAdmin" boolean DEFAULT FALSE,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__Admins__3214EC07819031DD" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Admins_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Moderators" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "AccountId" uuid NOT NULL,
    "FullName" character varying(256) NOT NULL,
    "Region" character varying(100),
    CONSTRAINT "PK__Moderato__3214EC0795EBEFC1" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Moderators_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Users" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "AccountId" uuid NOT NULL,
    "FullName" character varying(256) NOT NULL,
    "SubscriptionTier" text,
    "SubscriptionExpires" timestamp with time zone,
    "AvatarUrl" text,
    "BusinessAttribute" character varying(50) NOT NULL DEFAULT 'normal',
    CONSTRAINT "PK__Users__3214EC07A9E6FEE1" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Notifications" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "UserId" uuid NOT NULL,
    "Message" character varying(1000) NOT NULL,
    "Type" character varying(100) NOT NULL,
    "Link" character varying(500),
    "IsRead" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "RelatedId" uuid,
    CONSTRAINT "PK_Notifications" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Notifications_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
);


CREATE TABLE "WorkspaceFederations" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "Name" character varying(256) NOT NULL,
    "JoinCode" character varying(20) NOT NULL,
    "OwnerId" uuid NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "SettingsJson" text,
    CONSTRAINT "PK_WorkspaceFederations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WorkspaceFederations_Users" FOREIGN KEY ("OwnerId") REFERENCES "Users" ("Id")
);


CREATE TABLE "Workspaces" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "Name" character varying(256) NOT NULL,
    "JoinCode" character varying(20) NOT NULL,
    "InviteCode" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "OwnerId" uuid NOT NULL,
    "PackageTier" character varying(50) DEFAULT 'Free',
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "WorkspaceType" character varying(50) NOT NULL DEFAULT 'Personal',
    "CompanyName" character varying(256),
    "CompanyTaxCode" character varying(100),
    "CompanyAddress" character varying(500),
    "FederationId" uuid,
    "SettingsJson" text,
    CONSTRAINT "PK__Workspac__3214EC07B6F57A39" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Workspaces_Users" FOREIGN KEY ("OwnerId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Workspaces_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id") ON DELETE SET NULL
);


CREATE TABLE "AuditLogs" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "WorkspaceId" uuid,
    "FederationId" uuid,
    "UserId" uuid NOT NULL,
    "Action" character varying(100) NOT NULL,
    "TargetType" character varying(100) NOT NULL,
    "TargetId" uuid NOT NULL,
    "Metadata" text,
    "Timestamp" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__AuditLog__3214EC073CF0EA63" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Audit_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Audit_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id"),
    CONSTRAINT "FK_Audit_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "Billings" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "WorkspaceId" uuid NOT NULL,
    "PackageId" character varying(100) NOT NULL,
    "Status" character varying(50) DEFAULT 'Active',
    "EndDate" timestamp with time zone NOT NULL,
    "Amount" numeric,
    "UserId" uuid,
    "PaymentMethod" text,
    "TransactionRef" text,
    "CreatedAt" timestamp with time zone,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__Billings__3214EC072FFC9B7A" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Billing_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "ChatRooms" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "WorkspaceId" uuid,
    "FederationId" uuid,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__ChatRoom__3214EC07C4EF6540" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Chat_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id"),
    CONSTRAINT "FK_Chat_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "TaskCategories" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "WorkspaceId" uuid NOT NULL,
    "Name" character varying(256) NOT NULL,
    "Description" text,
    "ColorHex" character varying(7) NOT NULL DEFAULT '#3B82F6',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_TaskCategories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TaskCategories_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "WorkspaceFederationMembers" (
    "FederationId" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "PersonalWorkspaceId" uuid,
    "JoinedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "Role" character varying(50) NOT NULL DEFAULT 'Member',
    "Status" character varying(50) NOT NULL DEFAULT 'Active',
    CONSTRAINT "PK_WorkspaceFederationMembers" PRIMARY KEY ("FederationId", "UserId"),
    CONSTRAINT "FK_FedMembers_Federations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id"),
    CONSTRAINT "FK_FedMembers_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_FedMembers_Workspaces" FOREIGN KEY ("PersonalWorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "WorkspaceInvitations" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "WorkspaceId" uuid,
    "FederationId" uuid,
    "InviterId" uuid NOT NULL,
    "InviteeEmail" character varying(256) NOT NULL,
    "Role" character varying(50) NOT NULL DEFAULT 'Member',
    "DisplayRole" character varying(100),
    "Status" character varying(50) NOT NULL DEFAULT 'Pending',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_WorkspaceInvitations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Invitations_Inviter" FOREIGN KEY ("InviterId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Invitations_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id"),
    CONSTRAINT "FK_Invitations_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "WorkspaceMembers" (
    "WorkspaceId" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "Role" character varying(50) DEFAULT 'Member',
    "JoinedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "DisplayRole" character varying(100),
    "CanDeleteFile" boolean DEFAULT FALSE,
    "CanCreateTask" boolean DEFAULT TRUE,
    "CanEditTask" boolean DEFAULT TRUE,
    CONSTRAINT "PK__Workspac__193FE915758A3E39" PRIMARY KEY ("WorkspaceId", "UserId"),
    CONSTRAINT "FK_Members_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Members_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "ChatMessages" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "RoomId" uuid NOT NULL,
    "SenderId" uuid NOT NULL,
    "Content" text NOT NULL,
    "SentAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "IsDeleted" boolean DEFAULT FALSE,
    "ParentId" uuid,
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK__ChatMess__3214EC0776DADC06" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ChatMessages_ChatMessages_ParentId" FOREIGN KEY ("ParentId") REFERENCES "ChatMessages" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Messages_Rooms" FOREIGN KEY ("RoomId") REFERENCES "ChatRooms" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Messages_Users" FOREIGN KEY ("SenderId") REFERENCES "Users" ("Id")
);


CREATE TABLE "KpiTargets" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "WorkspaceId" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "CategoryId" uuid NOT NULL,
    "PeriodType" character varying(20) NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NOT NULL,
    "TargetValue" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_KpiTargets" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_KpiTargets_Categories" FOREIGN KEY ("CategoryId") REFERENCES "TaskCategories" ("Id"),
    CONSTRAINT "FK_KpiTargets_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_KpiTargets_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Tasks" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "WorkspaceId" uuid,
    "FederationId" uuid,
    "AssigneeId" uuid,
    "Title" character varying(512) NOT NULL,
    "Description" text,
    "Status" integer DEFAULT 0,
    "Priority" integer DEFAULT 1,
    "DueDate" timestamp with time zone,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "CategoryId" uuid,
    "IsCounterTask" boolean NOT NULL DEFAULT FALSE,
    "TargetCount" integer NOT NULL DEFAULT 1,
    "CurrentCount" integer NOT NULL DEFAULT 0,
    CONSTRAINT "PK__Tasks__3214EC077E71A0AA" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Tasks_Categories" FOREIGN KEY ("CategoryId") REFERENCES "TaskCategories" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Tasks_Users" FOREIGN KEY ("AssigneeId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Tasks_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id"),
    CONSTRAINT "FK_Tasks_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


CREATE TABLE "PersonalSchedules" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "UserId" uuid NOT NULL,
    "Title" character varying(256) NOT NULL,
    "Description" text,
    "StartTime" timestamp with time zone NOT NULL,
    "EndTime" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "TaskId" uuid,
    "TimeZone" character varying(100) DEFAULT 'UTC',
    CONSTRAINT "PK_PersonalSchedules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PersonalSchedules_Tasks" FOREIGN KEY ("TaskId") REFERENCES "Tasks" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_PersonalSchedules_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
);


CREATE TABLE "TaskComments" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "TaskId" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "Content" text NOT NULL,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    "ParentId" uuid,
    CONSTRAINT "PK__TaskComm__3214EC0701A1C24C" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Comments_Tasks" FOREIGN KEY ("TaskId") REFERENCES "Tasks" ("Id"),
    CONSTRAINT "FK_Comments_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_TaskComments_TaskComments_ParentId" FOREIGN KEY ("ParentId") REFERENCES "TaskComments" ("Id") ON DELETE SET NULL
);


CREATE TABLE "WorkspaceFiles" (
    "Id" uuid NOT NULL DEFAULT (gen_random_uuid()),
    "IsDisabled" boolean NOT NULL DEFAULT FALSE,
    "WorkspaceId" uuid,
    "TaskId" uuid,
    "UserId" uuid NOT NULL,
    "FileName" character varying(512) NOT NULL,
    "FileUrl" text NOT NULL,
    "FileType" character varying(100) NOT NULL,
    "FileSize" bigint NOT NULL,
    "IsPublic" boolean NOT NULL,
    "FederationId" uuid,
    "CreatedAt" timestamp with time zone DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK__Workspac__3214EC07AD2BE646" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Files_Tasks" FOREIGN KEY ("TaskId") REFERENCES "Tasks" ("Id"),
    CONSTRAINT "FK_Files_Users" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id"),
    CONSTRAINT "FK_Files_WorkspaceFederations" FOREIGN KEY ("FederationId") REFERENCES "WorkspaceFederations" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Files_Workspaces" FOREIGN KEY ("WorkspaceId") REFERENCES "Workspaces" ("Id")
);


